class Solution {
    int solve(vector<int>& nums, bool zeroLast) {
        int n = nums.size(), answer = 0;
        vector<int> seen(n);
        for (int i = 0; i < n; ++i) {
            if (seen[i]) continue;
            int cur = i, length = 0;
            bool containsZero = false;
            while (!seen[cur]) {
                seen[cur] = 1;
                int value = nums[cur];
                containsZero |= value == 0;
                cur = zeroLast ? (value == 0 ? n - 1 : value - 1) : value;
                ++length;
            }
            if (length > 1) answer += length - 1 + (containsZero ? 0 : 2);
        }
        return answer;
    }
public:
    int sortArray(vector<int>& nums) { return min(solve(nums, false), solve(nums, true)); }
};
